+    x: 0.7,
+    y: 0.78,
+    w: 8.6,
+    h: 0,
+    line: { color: theme.light, width: 1 }
+  });
+}
+
+function addSlideHeader(slide, theme, title, subtitle) {
+  slide.addText(title, {
+    x: 0.7,
+    y: 0.35,
+    w: 8.6,
+    h: 0.5,
+    fontFace: theme.fonts.header,
+    fontSize: 26,
+    color: theme.primary,
+    bold: true
+  });
+
+  if (subtitle) {
+    slide.addText(subtitle, {
+      x: 0.7,
+      y: 0.86,
+      w: 8.6,
+      h: 0.35,
+      fontFace: theme.fonts.body,
+      fontSize: 14,
+      color: theme.secondary,
+      bold: false
+    });
+  }
+
+  addTopRule(slide, theme);
+}
+
+function addPageBadge(slide, theme, pageNumber) {
+  slide.addShape("roundRect", {
+    x: 9.15,
+    y: 5.08,
+    w: 0.55,
+    h: 0.32,
+    fill: { color: theme.primary },
+    line: { color: theme.primary }
+  });
+  slide.addText(String(pageNumber), {
+    x: 9.15,
+    y: 5.08,
+    w: 0.55,
+    h: 0.32,
+    fontFace: theme.fonts.body,
+    fontSize: 12,
+    color: theme.bg,
+    bold: true,
+    align: "center",
+    valign: "mid"
+  });
+}
+
+module.exports = {
+  buildTheme,
+  addSlideHeader,
+  addPageBadge
+};
+
*** End Patch
