+    bold: true
+  });
+
+  slide.addText("From Technology Hammer to Real Value", {
+    x: 0.7,
+    y: 2.05,
+    w: 6.3,
+    h: 0.65,
+    fontFace: theme.fonts.body,
+    fontSize: 24,
