+
+  // Attribution + date (from brief)
+  slide.addText("Sequoia Capital analysis (September 2023)", {
+    x: 0.7,
+    y: 4.85,
+    w: 6.7,
+    h: 0.4,
+    fontFace: theme.fonts.body,
+    fontSize: 14,
+    color: theme.secondary,
+    bold: false
+  });
+
+  // Visual framing: right-side motif (three stacked waves)
+  const baseX = 7.05;
+  const cardW = 2.6;
+  const cardH = 1.35;
+  const gap = 0.18;
+  const wave = [
+    { label: "Compute", years: "6 decades", color: theme.primary },
+    { label: "Training data", years: "4 decades", color: theme.secondary },
+    { label: "Distribution", years: "2 decades", color: theme.accent }
+  ];
+  wave.forEach((w, i) => {
+    const y = 1.25 + i * (cardH + gap);
+    slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
+      x: baseX,
+      y,
+      w: cardW,
+      h: cardH,
+      fill: { color: w.color, transparency: 8 },
+      line: { color: w.color, transparency: 0 }
+    });
+    slide.addText(w.label, {
+      x: baseX + 0.2,
+      y: y + 0.2,
+      w: cardW - 0.4,
+      h: 0.4,
+      fontFace: theme.fonts.body,
+      fontSize: 16,
+      color: theme.primary,
+      bold: true
+    });
+    slide.addText(w.years, {
+      x: baseX + 0.2,
+      y: y + 0.62,
+      w: cardW - 0.4,
+      h: 0.5,
+      fontFace: theme.fonts.body,
+      fontSize: 22,
+      color: theme.primary,
+      bold: true
+    });
+  });
+
+  // Small footer source
+  slide.addText("Source: sequoiacap.com/article/generative-ai-act-two/", {
+    x: 0.7,
+    y: 5.25,
+    w: 8.3,
+    h: 0.3,
+    fontFace: theme.fonts.body,
+    fontSize: 10,
+    color: theme.accent,
+    bold: false
+  });
+
+  return slide;
+}
+
+if (require.main === module) {
+  const pptxgen = require("pptxgenjs");
+  const { buildTheme } = require("./theme");
+  const pres = new pptxgen();
+  pres.layout = "LAYOUT_16x9";
+  createSlide(pres, buildTheme());
+  pres.writeFile({ fileName: path.join(__dirname, "output", "slide-01-preview.pptx") });
+}
+
+module.exports = { createSlide, slideConfig };
+
*** End Patch
PATCH

