+      h: rowH,
+      fill: { color: theme.bg },
+      line: { color: theme.light }
+    });
+
+    slide.addText(r.headline, {
+      x: leftX + 2.02,
+      y: y + 0.14,
+      w: w - 2.1,
+      h: 0.35,
+      fontFace: theme.fonts.body,
+      fontSize: 18,
+      color: theme.primary,
+      bold: true
+    });
+
+    slide.addText(r.detail, {
+      x: leftX + 2.02,
+      y: y + 0.52,
+      w: w - 2.1,
+      h: 0.45,
+      fontFace: theme.fonts.body,
+      fontSize: 14,
+      color: theme.secondary,
+      bold: false
+    });
+  });
+
+  // Convergence arrow
