+    w: w - 0.5,
+    h: 0.35,
+    fontFace: theme.fonts.body,
+    fontSize: 16,
+    color: theme.primary,
+    bold: true
+  });
+
+  // Median badge
+  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
+    x: x + w - 1.55,
+    y: y + 0.1,
+    w: 1.3,
+    h: 0.4,
+    fill: { color: theme.primary, transparency: 10 },
+    line: { color: theme.primary }
+  });
+  slide.addText(medianLabel, {
+    x: x + w - 1.55,
+    y: y + 0.1,
+    w: 1.3,
+    h: 0.4,
+    fontFace: theme.fonts.body,
+    fontSize: 12,
+    color: theme.primary,
+    bold: true,
+    align: "center",
+    valign: "mid"
+  });
+
+  const plotX = x + 0.25;
+  const plotY = y + 0.62;
+  const plotW = w - 0.5;
+  const plotH = h - 0.82;
+
+  // Axis baseline
+  slide.addShape(pres.shapes.LINE, {
+    x: plotX,
+    y: plotY + plotH,
+    w: plotW,
+    h: 0,
+    line: { color: theme.light, width: 1 }
+  });
+
+  const rowH = plotH / items.length;
+  const barH = Math.min(0.22, rowH * 0.6);
+
+  items.forEach((it, idx) => {
+    const cy = plotY + idx * rowH + (rowH - barH) / 2;
+    const labelW = plotW * 0.48;
